def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = day_context.get('supply', 0.0)
    day = day_context.get('day', 0)

    budget = float(my_status.get('budget', 0.0))
    hp = int(my_status.get('hp', 0))
    no_water_days = int(my_status.get('no_water_days', 0))

    alive_opponents = []
    for opp_id, opp in opponents_status.items():
        if opp and opp.get('alive', False):
            alive_opponents.append(opp)

    if not alive_opponents:
        return max(0.0, min(budget, DAILY_SALARY * 0.4))

    # Extract yesterday bids (immediate reaction only)
    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {}) or {}
        bid = prev.get('bid', None)
        if bid is not None:
            try:
                yesterday_bids.append(float(bid))
            except Exception:
                pass

    pressure_bid = 0.0
    if yesterday_bids:
        pressure_bid = max(yesterday_bids)

    # Estimate how tight supply is relative to our requirement
    # (supply is total available water; higher supply means we can afford lower bid)
    supply_ratio = float(supply) / float(WATER_REQ) if WATER_REQ > 0 else 0.0

    # Base bid: competitive in medium scenario; adjust by HP and no-water streak
    # If supply is tight (< ~2x requirement), increase urgency.
    tightness = 1.0
    if supply_ratio >= 2.0:
        tightness = 0.85
    elif supply_ratio >= 1.5:
        tightness = 1.0
    else:
        tightness = 1.15

    # React to yesterday's max bid pressure: if they were willing to pay near/above 0.85*salary, match/beat slightly.
    high_pressure = pressure_bid >= (DAILY_SALARY * 0.85)

    if high_pressure:
        if hp <= 2 or no_water_days >= 2:
            target = DAILY_SALARY * 0.95 * tightness
        elif hp <= 3 or no_water_days >= 1:
            target = DAILY_SALARY * 0.75 * tightness
        else:
            target = min(DAILY_SALARY * 0.65 * tightness, pressure_bid + 3.0)
    else:
        # Lower pressure: bid moderately, but still secure water if we're at risk.
        if hp <= 2 or no_water_days >= 2:
            target = DAILY_SALARY * 0.85 * tightness
        elif hp <= 3 or no_water_days >= 1:
            target = DAILY_SALARY * 0.65 * tightness
        else:
            target = DAILY_SALARY * 0.55 * tightness

    # Clamp to budget and a reasonable upper bound.
    target = float(target)
    if budget <= 0.0:
        return 0.0

    # Avoid overcommitting when budget is low.
    if budget < DAILY_SALARY:
        target = min(target, budget * 0.9)

    # Final clamp: cannot exceed budget.
    bid = max(0.0, min(budget, target))
    return bid

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = float(my_status['hp'])
    budget = float(my_status['budget'])
    no_water = int(my_status['no_water_days'])

    if budget <= 0:
        return 0.0

    alive = []
    prev_bids = []
    high_pressure = 0
    desperate_count = 0

    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            if int(opp.get('no_water_days', 0)) >= 1 or float(opp.get('hp', 10)) <= 4:
                desperate_count += 1
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                b = float(prev['bid'])
                prev_bids.append(b)
                if b >= 120:
                    high_pressure += 1

    if not alive:
        return max(0.0, min(budget, 18.0))

    slots = max(1, int(supply // WATER_REQ))
    competitors = len(alive) + 1
    tightness = competitors - slots

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    danger = 0
    if hp <= 2:
        danger += 3
    elif hp <= 4:
        danger += 2
    elif hp <= 6:
        danger += 1
    danger += no_water

    if no_water >= 2 or hp <= 2:
        bid = max(125.0, highest_prev + 3.0)
    elif slots >= 2 and supply >= 20 and danger == 0:
        bid = 24.0 + 2.0 * max(0, tightness)
    elif slots >= 2 and danger <= 1:
        bid = 38.0 + 4.0 * max(0, tightness)
    else:
        bid = 62.0 + 8.0 * max(0, tightness)

    if highest_prev >= 140:
        if danger == 0 and slots >= 2:
            bid = min(bid, 42.0)
        else:
            bid = max(bid, 96.0)
    elif highest_prev >= 100:
        if danger >= 2:
            bid = max(bid, min(110.0, highest_prev + 2.0))
        else:
            bid = max(bid, 48.0)
    elif prev_bids:
        if danger >= 2:
            bid = max(bid, avg_prev + 4.0)
        else:
            bid = max(bid, avg_prev * 0.6)

    if desperate_count >= 2 and slots == 1:
        bid += 12.0
    elif desperate_count == 0 and slots >= 2 and hp >= 7:
        bid -= 8.0

    if day >= 8:
        bid += 8.0 * danger

    reserve_target = DAILY_SALARY * max(0, 10 - day) * 0.35
    max_affordable = budget
    if budget > reserve_target:
        max_affordable = max(0.0, budget - reserve_target * 0.25)

    bid = min(bid, max_affordable)
    bid = min(bid, budget)
    bid = max(0.0, bid)
    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
