    DAILY_SALARY = 150
    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    if not alive_opponents:
        return int(min(my_status['budget'], DAILY_SALARY * 0.5))
    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])
    base_bid = DAILY_SALARY * 0.9
    if yesterday_bids:
        max_prev = max(yesterday_bids)
        base_bid = max(int(max_prev + 1), int(DAILY_SALARY * 0.6))
    if my_status['hp'] <= 2:
        base_bid = max(base_bid, DAILY_SALARY * 0.95)
    elif my_status['hp'] > 8:
        base_bid = min(base_bid, DAILY_SALARY * 0.8)
    bid = int(min(my_status['budget'], base_bid))
    bid = max(bid, 1)

